OUT = ROOT / 'audits' / '2026-11-10'
BASE = '80075f6b6f219155c5764243642ea9671a0756d9'
before = subprocess.check_output(['git', 'show', BASE + ':index.html'], cwd=ROOT).decode('utf-8')
