checks = json.loads((OUT / 'study-regression.json').read_text(encoding='utf-8'))
scans = json.loads((OUT / 'study-accessibility.json').read_text(encoding='utf-8'))
assert not checks['errors'] and all(not scan['violations'] for scan in scans)
