for pattern in [r'<article class="word-card"[\s\S]*?</article>', r'data:image/[\w.+-]+;base64,[A-Za-z0-9+/=]+']:
    assert re.findall(pattern, before) == re.findall(pattern, after)
for key in ['vocab-data', 'sentence-data', 'phrase-data', 'work-data', 'novel-dict', 'grammar-data']:
    pattern = r'<script[^>]*id="' + key + r'"[^>]*>([\s\S]*?)</script>'
    assert json.loads(re.search(pattern, before)[1]) == json.loads(re.search(pattern, after)[1])
summary = {'version': '2.8.0', 'build': json.loads((ROOT / 'version.json').read_text())['build'],
           'original_content_preserved': True, 'main_vocabulary_cards': 2199, 'embedded_images': 2500,
           'reading_texts': 9, 'reading_questions': 27, 'new_end_to_end_checks': len(checks['results']),
           'viewport_checks': 56, 'theme_accessibility_scans': len(scans), 'collapsed_sidebar_scan': 'passed',
           'simulated_media': True, 'simulated_ai': True}
(OUT / 'learning-summary.json').write_text(json.dumps(summary, ensure_ascii=False, indent=2), encoding='utf-8')
rows = ''.join('<tr><td>' + html.escape(item['name']) + '</td><td>Geçti</td></tr>' for item in checks['results'])
